package com.bank.wirerouting.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Bellman-Ford style relaxation bounded by a maximum number of hops.
public class WireRoutingService {
    private static final Logger log = Logger.getLogger(WireRoutingService.class.getName());

    public int cheapestWithin(int n, int[][] flights, int src, int dst, int k) {
        final int INF = Integer.MAX_VALUE;
        int[] cost = new int[n];
        Arrays.fill(cost, INF);
        cost[src] = 0;                                   // source costs nothing
        for (int round = 0; round <= k; round++) {        // k stops = k+1 edges
            int[] snap = cost.clone();                    // frozen previous round
            for (int[] f : flights) {
                int u = f[0], v = f[1], p = f[2];
                if (snap[u] != INF && snap[u] + p < cost[v]) {
                    cost[v] = snap[u] + p;                // relax one hop only
                }
            }
        }
        int answer = cost[dst] == INF ? -1 : cost[dst];
        log.info(() -> "Cheapest wire cost within " + k + " stops = " + answer);
        return answer;
    }
}
