package com.bank.wirerouting;

import com.bank.wirerouting.service.WireRoutingService;
import java.util.logging.Logger;

public class WireRoutingApplication {
    private static final Logger log = Logger.getLogger(WireRoutingApplication.class.getName());

    public static void main(String[] args) {
        WireRoutingService service = new WireRoutingService();
        // 0=SRC, 1=A, 2=DST. Correspondent-bank fees in rupees (scaled).
        int[][] flights = { {0, 1, 100}, {1, 2, 100}, {0, 2, 500} };
        int fee = service.cheapestWithin(3, flights, 0, 2, 1); // at most 1 stop
        log.info(() -> "Final cheapest fee chosen = " + fee);
    }
}
